export function resolveBlogPostSlug(slug: string): string {
  const aliases: Record<string, string> = {
    "how-to-merge-pdfs": "2026-08-21-how-to-merge-pdf-files-online-for-free-in-2026",
    "best-free-pdf-compressor": "2026-08-21-how-to-compress-pdf-files-without-losing-quality",
    "how-to-convert-pdf-to-word": "2026-08-21-how-to-convert-pdf-to-word-for-free-editable-documents",
    "how-to-convert-image-to-text-using-ocr": "2026-08-21-how-to-extract-text-from-pdf-copy-text-from-scanned-pdfs",
  };

  return aliases[slug] ?? slug;
}

export function findTool(slug: string): ToolRecord | undefined {
  return tools.find((tool) => tool.slug === slug);
}

export function findBlogPost(slug: string): BlogPostRecord | undefined {
  const resolvedSlug = resolveBlogPostSlug(slug);
  return blogPosts.find((post) => post.slug === resolvedSlug);
}
